const trig = $('Sub-workflow Input').first()?.json || {};
const ctx = $('Resolve Tenant Context').first()?.json || {};
const scope = String(trig.scope || 'deals').toLowerCase();
const limit = Math.min(parseInt(trig.limit, 10) || 10, 50);
const recordId = String(trig.recordId || '').trim();
const query = String(trig.query || '').trim();
const orgCfg = (ctx.orgConfig && typeof ctx.orgConfig === 'object') ? ctx.orgConfig : {};
const fbCfg = (trig.fallbackOrgConfig && typeof trig.fallbackOrgConfig === 'object') ? trig.fallbackOrgConfig : {};
const cfg = Object.assign({}, fbCfg, orgCfg);
const envelope = {
  ok: false, status: 'refused', reasonCode: 'none', guidance: 'none', userMessage: null,
  connectorId: 'zoho.crm', organizationId: ctx.organizationId || null, userId: ctx.userId || null,
  contextSource: ctx.contextSource || 'fallback', degraded: ctx.degraded === true,
  records: [], total: 0, error: null,
  diagnostics: { requestId: 'zcr-' + ($execution.id || 'na') + '-' + Date.now(), workflow: 'prism-13-zoho-crm-service', scope: scope }
};
function refuse(code, msg, guidance) { envelope.status = 'refused'; envelope.reasonCode = code; envelope.userMessage = msg; envelope.guidance = guidance; return [{ json: envelope }]; }
if (ctx.enabled === false) return refuse('connector_disabled', 'Zoho CRM is turned off for you - enable it in Connections.', 'enable');
if (ctx.entitlement === false) return refuse('not_entitled', 'Your account does not have access to Zoho CRM - ask your admin to unlock it.', 'request_access');
if (!ctx.accessToken) return refuse('missing_token', 'Zoho CRM is not connected yet - connect your account in Connections to get started.', 'connect');
const dc = String(cfg.dataCenter || 'in').replace(/^zoho\./, '');
const apiBase = 'https://www.zohoapis.' + dc + '/crm/v2';
let url = ''; let scopeType = scope;
if (scope === 'deal') {
  if (!recordId) return refuse('empty', 'Provide a deal id to fetch a single Zoho CRM deal.', 'none');
  url = apiBase + '/Deals/' + encodeURIComponent(recordId); scopeType = 'deal';
} else if (scope === 'tasks' || scope === 'task') {
  url = apiBase + (recordId ? '/Tasks/' + encodeURIComponent(recordId) : '/Tasks?sort_by=Created_Time&sort_order=desc&per_page=' + limit); scopeType = 'tasks';
} else if (scope === 'contacts' || scope === 'contact') {
  url = apiBase + '/Contacts?sort_by=Created_Time&sort_order=desc&per_page=' + limit; scopeType = 'contacts';
} else if (scope === 'accounts' || scope === 'account') {
  url = apiBase + '/Accounts?sort_by=Created_Time&sort_order=desc&per_page=' + limit; scopeType = 'accounts';
} else if (scope === 'leads' || scope === 'lead') {
  url = apiBase + '/Leads?sort_by=Created_Time&sort_order=desc&per_page=' + limit; scopeType = 'leads';
} else {
  url = apiBase + '/Deals?sort_by=Modified_Time&sort_order=desc&per_page=' + limit; scopeType = 'deals';
}
return [{ json: Object.assign({}, envelope, { ok: true, status: 'pending', accessToken: ctx.accessToken, requestUrl: url, scopeType: scopeType }) }];

const res = $input.first()?.json || {};
const meta = $('Gate & Build Request').first()?.json || {};
const scope = (meta.diagnostics && meta.diagnostics.scope) || 'unknown';
const envelope = {
  ok: false, status: 'error', reasonCode: 'provider_error', guidance: 'retry',
  userMessage: 'Zoho CRM returned an error - try again shortly. If it persists, check the connection in Connections.',
  connectorId: 'zoho.crm', organizationId: meta.organizationId || null, userId: meta.userId || null,
  contextSource: meta.contextSource || 'fallback', degraded: meta.degraded === true,
  records: [], total: 0, error: null,
  diagnostics: { requestId: (meta.diagnostics && meta.diagnostics.requestId) || ('zcr-' + Date.now()), workflow: 'prism-13-zoho-crm-service' }
};
const httpStatus = (res.error && (res.error.status || res.error.statusCode)) || res.statusCode || null;
const errCode = res.error && res.error.code ? String(res.error.code) : '';
function finishSuccess() { envelope.ok = true; envelope.status = 'success'; envelope.reasonCode = 'none'; envelope.guidance = 'none'; envelope.userMessage = null; envelope.error = null; }
const scopeType = meta.scopeType || 'deals';
if (res.code === 'AUTHENTICATION_FAILURE' || res.code === 'INVALID_TOKEN') { envelope.reasonCode = 'reauth_required'; envelope.guidance = 'reconnect'; envelope.userMessage = 'Your Zoho connection needs re-authentication - reconnect in Connections.'; envelope.error = { provider: 'zoho', httpStatus: httpStatus || 401, message: String(res.code), retryable: false }; return [{ json: envelope }]; }
if (res.code === 'OAUTH_SCOPE_MISMATCH' || res.code === 'NO_PERMISSION' || httpStatus === 403) { envelope.reasonCode = 'not_entitled'; envelope.guidance = 'request_access'; envelope.userMessage = 'The Zoho connection does not have permission for ' + scopeType + ' - ask your admin to grant module access.'; envelope.error = { provider: 'zoho', httpStatus: httpStatus || 403, message: String(res.code || 'NO_PERMISSION'), retryable: false }; return [{ json: envelope }]; }
if (res.code && res.code !== 'SUCCESS' && !Array.isArray(res.data)) { envelope.userMessage = 'Zoho CRM returned an error (' + String(res.code) + ') - try again shortly.'; envelope.error = { provider: 'zoho', httpStatus: httpStatus || null, message: String(res.code), retryable: true }; return [{ json: envelope }]; }
const raw = Array.isArray(res.data) ? res.data : [];
const records = raw.map(function (d) {
  if (scopeType === 'tasks') return { id: String(d.id || ''), subject: d.Subject || '', status: d.Status || '', priority: d.Priority || '', dueDate: d.Due_Date || '', relatedTo: (d.What_Id && d.What_Id.name) || '', owner: (d.Owner && d.Owner.name) || '' };
  if (scopeType === 'accounts') return { id: String(d.id || ''), name: d.Account_Name || '', website: d.Website || '', phone: d.Phone || '', billingCountry: d.Billing_Country || '' };
  if (scopeType === 'leads') return { id: String(d.id || ''), fullName: ((d.First_Name || '') + ' ' + (d.Last_Name || '')).trim(), company: d.Company || '', email: d.Email || '', phone: d.Phone || '', leadStatus: d.Lead_Status || '' };
  if (scopeType === 'contacts') return { id: String(d.id || ''), fullName: d.Full_Name || ((d.First_Name || '') + ' ' + (d.Last_Name || '')).trim(), email: d.Email || '', phone: d.Phone || '', title: d.Title || '', account: (d.Account_Name && d.Account_Name.name) || '' };
  return { id: String(d.id || ''), name: d.Deal_Name || '', stage: d.Stage || 'Qualification', amount: d.Amount != null ? Number(d.Amount) : 0, closingDate: d.Closing_Date || '', account: (d.Account_Name && d.Account_Name.name) || '', contact: (d.Contact_Name && d.Contact_Name.name) || '', owner: (d.Owner && d.Owner.name) || '', modifiedTime: d.Modified_Time || '' };
});
finishSuccess(); envelope.records = records; envelope.total = records.length; envelope.scope = scopeType;
return [{ json: envelope }];
